import{_ as a,o,c as e,a2 as r}from"./chunks/framework.C4u7U0Dw.js";const c=JSON.parse('{"title":"帮助中心：常见问题与故障排查","description":"","frontmatter":{},"headers":[],"relativePath":"help/index.md","filePath":"help/index.md"}'),d={name:"help/index.md"};function s(n,t,l,i,h,q){return o(),e("div",null,[...t[0]||(t[0]=[r(`<h1 id="帮助中心-常见问题与故障排查" tabindex="-1">帮助中心：常见问题与故障排查 <a class="header-anchor" href="#帮助中心-常见问题与故障排查" aria-label="Permalink to &quot;帮助中心：常见问题与故障排查&quot;">​</a></h1><blockquote><p>遇到问题先来这里。按&quot;症状 → 原因 → 解决&quot;查表，多数问题 1 分钟解决。解决不了再问我。</p></blockquote><h2 id="一、快速排查表-按症状查" tabindex="-1">一、快速排查表（按症状查） <a class="header-anchor" href="#一、快速排查表-按症状查" aria-label="Permalink to &quot;一、快速排查表（按症状查）&quot;">​</a></h2><table tabindex="0"><thead><tr><th>症状</th><th>可能原因</th><th>快速解决</th></tr></thead><tbody><tr><td>我找不到你给的文件</td><td>文件不在工作目录</td><td>把文件放进工作目录，或给我绝对路径</td></tr><tr><td>我回答的内容与你预期差很远</td><td>需求描述太模糊</td><td>用四要素补全（目标/输入/约束/验收），见第 2 章</td></tr><tr><td>我读不了某个文件</td><td>格式不支持或编码问题</td><td>告诉我文件格式，转成常见格式（txt/md/csv）</td></tr><tr><td>我执行命令失败</td><td>环境/权限问题</td><td>把完整报错发我，我按堆栈排查</td></tr><tr><td>输出是乱码</td><td>编码问题（常见 GBK/UTF-8）</td><td>告诉我原编码，统一转 UTF-8</td></tr><tr><td>本地预览/构建失败</td><td>依赖没装好</td><td>检查 node_modules，重装依赖</td></tr><tr><td>我&quot;一本正经说错话&quot;（幻觉）</td><td>没给资料/凭记忆答</td><td>给资料、要引用、让它读着答（见课外阅读第 2 节）</td></tr></tbody></table><h2 id="二、常用问题-faq" tabindex="-1">二、常用问题 FAQ <a class="header-anchor" href="#二、常用问题-faq" aria-label="Permalink to &quot;二、常用问题 FAQ&quot;">​</a></h2><h3 id="q1-momawork-rs-到底是什么" tabindex="-1">Q1：momawork-rs 到底是什么？ <a class="header-anchor" href="#q1-momawork-rs-到底是什么" aria-label="Permalink to &quot;Q1：momawork-rs 到底是什么？&quot;">​</a></h3><p>一个运行在 MomaWork 桌面程序里的 AI 工作助手。与聊天机器人的区别是：<strong>我拥有你的工作目录，能真正读写文件、执行命令、调用技能</strong>。详情见<a href="./../bluebook/第一篇 使用手册：先把我用起来/第 1 章 初识 momawork-rs.html">第 1 章</a>。</p><h3 id="q2-我看不到工作目录之外的文件-怎么办" tabindex="-1">Q2：我看不到工作目录之外的文件，怎么办？ <a class="header-anchor" href="#q2-我看不到工作目录之外的文件-怎么办" aria-label="Permalink to &quot;Q2：我看不到工作目录之外的文件，怎么办？&quot;">​</a></h3><p>把需要的文件<strong>复制或移动到工作目录</strong>，或给我文件的<strong>绝对路径</strong>。我就是&quot;生活在工作目录里的同事&quot;，目录之外的内容我默认看不到。</p><h3 id="q3-我能让你联网吗" tabindex="-1">Q3：我能让你联网吗？ <a class="header-anchor" href="#q3-我能让你联网吗" aria-label="Permalink to &quot;Q3：我能让你联网吗？&quot;">​</a></h3><p>取决于你提供的工具。我默认不能随意浏览互联网；你给链接、文件、或告诉我可用工具，我就能基于这些内容工作。<strong>重要信息请提供原文或链接，我不编造。</strong></p><h3 id="q4-你会删除我的文件吗" tabindex="-1">Q4：你会删除我的文件吗？ <a class="header-anchor" href="#q4-你会删除我的文件吗" aria-label="Permalink to &quot;Q4：你会删除我的文件吗？&quot;">​</a></h3><p><strong>不会主动删。</strong> 删除、覆盖、推送远程等不可逆操作，我都会<strong>先征得你确认</strong>再执行。如果遇到我请求确认，请看清再回答。</p><h3 id="q5-为什么我明明说了-你还是做错了" tabindex="-1">Q5：为什么我明明说了，你还是做错了？ <a class="header-anchor" href="#q5-为什么我明明说了-你还是做错了" aria-label="Permalink to &quot;Q5：为什么我明明说了，你还是做错了？&quot;">​</a></h3><p>90% 的&quot;做错&quot;来自两个环节：</p><ol><li><strong>需求没对齐</strong>：我没复述或你没纠正我的理解 → 回到<a href="./../bluebook/第一篇 使用手册：先把我用起来/第 2 章 第一次对话：把需求讲清楚.html">第 2 章</a>的&quot;复述确认法&quot;；</li><li><strong>没有中间检查</strong>：直接等最终结果 → 要求&quot;中间产物&quot;，先看大纲/计划再继续。</li></ol><h3 id="q6-记忆存在哪-安全吗" tabindex="-1">Q6：记忆存在哪？安全吗？ <a class="header-anchor" href="#q6-记忆存在哪-安全吗" aria-label="Permalink to &quot;Q6：记忆存在哪？安全吗？&quot;">​</a></h3><p>记忆存在项目对应的 <code>memory</code> 目录，是<strong>明文 Markdown 文件</strong>，你可以随时查看、修改、删除。请勿把密码、密钥等敏感信息写入记忆或项目文件。</p><h3 id="q7-任务做到一半断了-我忘了上次进度-怎么办" tabindex="-1">Q7：任务做到一半断了/我忘了上次进度，怎么办？ <a class="header-anchor" href="#q7-任务做到一半断了-我忘了上次进度-怎么办" aria-label="Permalink to &quot;Q7：任务做到一半断了/我忘了上次进度，怎么办？&quot;">​</a></h3><p>记忆系统会记录项目状态和上下文。恢复会话后，说&quot;继续上次的任务&quot;，我会读取记忆接着干。建议关键任务中途让它&quot;记录当前进度&quot;。</p><h3 id="q8-怎么让重复任务以后自动跑" tabindex="-1">Q8：怎么让重复任务以后自动跑？ <a class="header-anchor" href="#q8-怎么让重复任务以后自动跑" aria-label="Permalink to &quot;Q8：怎么让重复任务以后自动跑？&quot;">​</a></h3><p>把流程沉淀为 Skill（第 17 章）→ 再用自动化定期调用（第 15 章）。这样你只需要说&quot;生成本周周报&quot;，它就会按标准流程跑。</p><h2 id="三、故障排查流程-三步法" tabindex="-1">三、故障排查流程（三步法） <a class="header-anchor" href="#三、故障排查流程-三步法" aria-label="Permalink to &quot;三、故障排查流程（三步法）&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>1. 描述症状：发生了什么 + 完整的报错信息/截图/输出</span></span>
<span class="line"><span>2. 回顾改动：最近改了什么（文件/配置/环境）？</span></span>
<span class="line"><span>3. 最小复现：能不能用最小例子复现？能 → 一起定位；不能 → 现场排查</span></span></code></pre></div><div class="tip custom-block"><p class="custom-block-title">排查心态</p><p><strong>报错信息越完整，解决越快。</strong> 完整堆栈 + 触发步骤 + 最近改动，三样给齐，通常几分钟就能定位。</p></div><h2 id="四、联系与反馈" tabindex="-1">四、联系与反馈 <a class="header-anchor" href="#四、联系与反馈" aria-label="Permalink to &quot;四、联系与反馈&quot;">​</a></h2><ul><li><strong>遇到文档错误</strong>：告诉我具体章节和问题，我来修正；</li><li><strong>希望新增内容</strong>：描述你想要的场景，我评估后扩充白皮书；</li><li><strong>提出改进建议</strong>：任何让这本白皮书更好的想法，都欢迎直接说。</li></ul><p><a href="/MoMAWork-/">返回首页</a></p>`,28)])])}const p=a(d,[["render",s]]);export{c as __pageData,p as default};
